import{_ as e,c as i,o as n,j as s,Y as a,t as l}from"./chunks/framework.BNTND4LZ.js";const u=JSON.parse('{"title":"git-difftool | x-cmd man (git man1) | Show changes using common diff tools","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-difftool - Show changes using common diff tools","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-difftool | x-cmd man (git man1) | Show changes using common diff tools"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-difftool - Show changes using common diff tools"}]]},"headers":[],"params":{"isMan":true,"man":"git-difftool","category":"git man1","desc":"Show changes using common diff tools"},"relativePath":"git/man1/git-difftool.md","filePath":"git/man1/[man].md"}'),r={name:"git/man1/git-difftool.md"},f={class:"visually-hidden"};function d(o,t,g,h,p,c){return n(),i("div",null,[s("h1",f,l(o.$params.man),1),t[0]||(t[0]=a('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-difftool - Show changes using common diff tools</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> difftool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;options&gt;] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">commit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">commit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] [--] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><em>git difftool</em> is a Git command that allows you to compare and edit files between revisions using common diff tools. <em>git difftool</em> is a frontend to <em>git diff</em> and accepts the same options and arguments. See <strong>git-diff</strong>(1).</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-d, --dir-diff</p><blockquote><p>Copy the modified files to a temporary location and perform a directory diff on them. This mode never prompts before launching the diff tool.</p></blockquote><p>-y, --no-prompt</p><blockquote><p>Do not prompt before launching a diff tool.</p></blockquote><p>--prompt</p><blockquote><p>Prompt before each invocation of the diff tool. This is the default behaviour; the option is provided to override any configuration settings.</p></blockquote><p>--rotate-to=&lt;file&gt;</p><blockquote><p>Start showing the diff for the given path, the paths before it will move to end and output.</p></blockquote><p>--skip-to=&lt;file&gt;</p><blockquote><p>Start showing the diff for the given path, skipping all the paths before it.</p></blockquote><p>-t &lt;tool&gt;, --tool=&lt;tool&gt;</p><blockquote><p>Use the diff tool specified by &lt;tool&gt;. Valid values include emerge, kompare, meld, and vimdiff. Run <strong>git difftool --tool-help</strong> for the list of valid &lt;tool&gt; settings.</p><p>If a diff tool is not specified, <em>git difftool</em> will use the configuration variable <strong>diff.tool</strong>. If the configuration variable <strong>diff.tool</strong> is not set, <em>git difftool</em> will pick a suitable default.</p><p>You can explicitly provide a full path to the tool by setting the configuration variable <strong>difftool.&lt;tool&gt;.path</strong>. For example, you can configure the absolute path to kdiff3 by setting <strong>difftool.kdiff3.path</strong>. Otherwise, <em>git difftool</em> assumes the tool is available in PATH.</p><p>Instead of running one of the known diff tools, <em>git difftool</em> can be customized to run an alternative program by specifying the command line to invoke in a configuration variable <strong>difftool.&lt;tool&gt;.cmd</strong>.</p><p>When <em>git difftool</em> is invoked with this tool (either through the <strong>-t</strong> or <strong>--tool</strong> option or the <strong>diff.tool</strong> configuration variable) the configured command line will be invoked with the following variables available: <strong>$LOCAL</strong> is set to the name of the temporary file containing the contents of the diff pre-image and <strong>$REMOTE</strong> is set to the name of the temporary file containing the contents of the diff post-image. <strong>$MERGED</strong> is the name of the file which is being compared. <strong>$BASE</strong> is provided for compatibility with custom merge tool commands and has the same value as <strong>$MERGED</strong>.</p></blockquote><p>--tool-help</p><blockquote><p>Print a list of diff tools that may be used with <strong>--tool</strong>.</p></blockquote><p>--[no-]symlinks</p><blockquote><p><em>git difftool</em>&#39;s default behavior is create symlinks to the working tree when run in <strong>--dir-diff</strong> mode and the right-hand side of the comparison yields the same content as the file in the working tree.</p><p>Specifying <strong>--no-symlinks</strong> instructs <em>git difftool</em> to create copies instead. <strong>--no-symlinks</strong> is the default on Windows.</p></blockquote><p>-x &lt;command&gt;, --extcmd=&lt;command&gt;</p><blockquote><p>Specify a custom command for viewing diffs. <em>git-difftool</em> ignores the configured defaults and runs <strong>$command $LOCAL $REMOTE</strong> when this option is specified. Additionally, <strong>$BASE</strong> is set in the environment.</p></blockquote><p>-g, --[no-]gui</p><blockquote><p>When <em>git-difftool</em> is invoked with the <strong>-g</strong> or <strong>--gui</strong> option the default diff tool will be read from the configured <strong>diff.guitool</strong> variable instead of <strong>diff.tool</strong>. The <strong>--no-gui</strong> option can be used to override this setting. If <strong>diff.guitool</strong> is not set, we will fallback in the order of <strong>merge.guitool</strong>, <strong>diff.tool</strong>, <strong>merge.tool</strong> until a tool is found.</p></blockquote><p>--[no-]trust-exit-code</p><blockquote><p><em>git-difftool</em> invokes a diff tool individually on each file. Errors reported by the diff tool are ignored by default. Use <strong>--trust-exit-code</strong> to make <em>git-difftool</em> exit when an invoked diff tool returns a non-zero exit code.</p><p><em>git-difftool</em> will forward the exit code of the invoked tool when <strong>--trust-exit-code</strong> is used.</p></blockquote><p>See <strong>git-diff</strong>(1) for the full list of supported options.</p><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p><em>git difftool</em> falls back to <em>git mergetool</em> config variables when the difftool equivalents have not been defined.</p><p>Everything above this line in this section isn&#39;t included from the <strong>git-config</strong>(1) documentation. The content that follows is the same as what&#39;s found there:</p><p>diff.tool</p><blockquote><p>Controls which diff tool is used by <strong>git-difftool</strong>(1). This variable overrides the value configured in <strong>merge.tool</strong>. The list below shows the valid built-in values. Any other value is treated as a custom diff tool and requires that a corresponding difftool.&lt;tool&gt;.cmd variable is defined.</p></blockquote><p>diff.guitool</p><blockquote><p>Controls which diff tool is used by <strong>git-difftool</strong>(1) when the -g/--gui flag is specified. This variable overrides the value configured in <strong>merge.guitool</strong>. The list below shows the valid built-in values. Any other value is treated as a custom diff tool and requires that a corresponding difftool.&lt;guitool&gt;.cmd variable is defined.</p></blockquote><p>difftool.&lt;tool&gt;.cmd</p><blockquote><p>Specify the command to invoke the specified diff tool. The specified command is evaluated in shell with the following variables available: <em>LOCAL</em> is set to the name of the temporary file containing the contents of the diff pre-image and <em>REMOTE</em> is set to the name of the temporary file containing the contents of the diff post-image.</p><p>See the <strong>--tool=&lt;tool&gt;</strong> option in <strong>git-difftool</strong>(1) for more details.</p></blockquote><p>difftool.&lt;tool&gt;.path</p><blockquote><p>Override the path for the given tool. This is useful in case your tool is not in the PATH.</p></blockquote><p>difftool.trustExitCode</p><blockquote><p>Exit difftool if the invoked diff tool returns a non-zero exit status.</p><p>See the <strong>--trust-exit-code</strong> option in <strong>git-difftool</strong>(1) for more details.</p></blockquote><p>difftool.prompt</p><blockquote><p>Prompt before each invocation of the diff tool.</p></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-diff</strong>(1)</p><blockquote><p>Show changes between commits, commit and working tree, etc</p></blockquote><p><strong>git-mergetool</strong>(1)</p><blockquote><p>Run merge conflict resolution tools to resolve merge conflicts</p></blockquote><p><strong>git-config</strong>(1)</p><blockquote><p>Get and set repository or global options</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>',54))])}const k=e(r,[["render",d]]);export{u as __pageData,k as default};
